 static class MotionEvent {static final int ACTION_DOWN=0,ACTION_UP=1,ACTION_CANCEL=3;int action;float x,y;long time;MotionEvent(int a,float x,long t){action=a;this.x=x;y=1;time=t;}int getActionMasked(){return action;}float getX(){return x;}float getY(){return y;}long getEventTime(){return time;}}
